import os
from typing import Iterable, Iterator, Optional

from google.cloud import speech


def start_streaming_recognizer(
    audio_chunks: Iterable[bytes],
    language_code: str = "en-US",
    enable_punctuation: bool = True,
    sample_rate_hz: int = 16000,
    encoding: speech.RecognitionConfig.AudioEncoding = speech.RecognitionConfig.AudioEncoding.LINEAR16,
) -> Iterator[str]:
    client = speech.SpeechClient()

    config = speech.RecognitionConfig(
        encoding=encoding,
        sample_rate_hertz=sample_rate_hz,
        language_code=language_code,
        enable_automatic_punctuation=enable_punctuation,
        model="latest_long",
    )

    streaming_config = speech.StreamingRecognitionConfig(
        config=config,
        interim_results=True,
        single_utterance=False,
    )

    def request_generator() -> Iterator[speech.StreamingRecognizeRequest]:
        for chunk in audio_chunks:
            if chunk:
                yield speech.StreamingRecognizeRequest(audio_content=chunk)

    responses = client.streaming_recognize(
        config=streaming_config,
        requests=request_generator(),
    )

    for response in responses:
        for result in response.results:
            if not result.alternatives:
                continue
            transcript = result.alternatives[0].transcript
            if transcript:
                yield transcript


def main() -> None:
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("Usage: python script.py <audio_linear16_raw_file>")

    audio_path = sys.argv[1]
    with open(audio_path, "rb") as f:
        def chunks() -> Iterator[bytes]:
            while True:
                data = f.read(4096)
                if not data:
                    break
                yield data

        for transcript in start_streaming_recognizer(chunks()):
            print(transcript)


if __name__ == "__main__":
    main()
